package com.fairyringmap;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The code-label solver, tested against the real forty-two rather than against invented points.
 * <p>
 * Synthetic cases prove the rules; only the shipped definitions prove the map is actually
 * labellable, and that is the question the feature turns on. The marker positions here are
 * projected exactly as {@code layoutIcons} projects them, nudges included, so a change to the world
 * box or to {@code NUDGES} moves these tests too.
 */
public class LabelPlacementTest
{
	private static final int LABEL_WIDTH = 20;
	private static final int LABEL_HEIGHT = 10;
	private static final int MARKER_RADIUS = 5;

	private FairyRingDefinitions definitions;
	private List<LabelPlacement.Anchor> surface;

	@Before
	public void setUp() throws Exception
	{
		try (InputStream in = getClass().getResourceAsStream("/FairyRingMap/FairyRingDefinitions.json");
			 Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			definitions = new Gson().fromJson(reader, FairyRingDefinitions.class);
		}

		MapDefinition map = definitions.getMap();
		MapProjection projection = new MapProjection(
			map.getWorldX0(), map.getWorldY0(), map.getWorldX1(), map.getWorldY1(),
			map.getSpriteWidth(), map.getSpriteHeight());

		surface = new ArrayList<>();
		for (RingDefinition ring : definitions.getRings())
		{
			if (!ring.isOnSurface())
			{
				continue;
			}
			surface.add(new LabelPlacement.Anchor(
				ring.getCode(),
				projection.pixelX(ring.getWorldX()) + ring.getOffsetX(),
				projection.pixelY(ring.getWorldY()) + ring.getOffsetY()));
		}
	}

	private Map<String, LabelPlacement> solveSurface(List<LabelPlacement.Anchor> wanted)
	{
		MapDefinition map = definitions.getMap();
		return LabelPlacement.solve(wanted, surface,
			LABEL_WIDTH, LABEL_HEIGHT, MARKER_RADIUS,
			0, 0, map.getSpriteWidth(), map.getSpriteHeight());
	}

	/**
	 * The feature's premise. If this fails the map cannot carry every code, and the config's
	 * "every destination" mode is silently showing fewer than it claims.
	 */
	@Test
	public void everySurfaceRingGetsALabel()
	{
		// Pinned before the real assertion, which compares two counts and would therefore pass
		// on an empty list. Forty-two is what FairyRingDefinitionsTest independently expects.
		assertEquals("the surface set is not what the definitions hold", 42, surface.size());

		Map<String, LabelPlacement> placed = solveSurface(surface);
		assertEquals("some surface rings could not be labelled: " + missing(placed),
			surface.size(), placed.size());
	}

	/**
	 * The failure a single fixed offset produces, and the reason the solver exists: nine labels
	 * landing on a different ring's marker. A label over a marker hides a click target.
	 */
	@Test
	public void noLabelCoversAnotherRingsMarker()
	{
		Map<String, LabelPlacement> placed = solveSurface(surface);
		for (LabelPlacement.Anchor anchor : surface)
		{
			int[] box = boxFor(anchor, placed.get(anchor.getKey()));
			for (LabelPlacement.Anchor other : surface)
			{
				if (other == anchor)
				{
					continue;
				}
				int[] marker = boxFor(other, null);
				assertFalse(anchor.getKey() + "'s label covers " + other.getKey() + "'s marker",
					intersects(box, marker, MARKER_RADIUS));
			}
		}
	}

	@Test
	public void noTwoLabelsOverlap()
	{
		Map<String, LabelPlacement> placed = solveSurface(surface);
		List<LabelPlacement.Anchor> all = new ArrayList<>(surface);
		for (int i = 0; i < all.size(); i++)
		{
			for (int j = i + 1; j < all.size(); j++)
			{
				int[] a = boxFor(all.get(i), placed.get(all.get(i).getKey()));
				int[] b = boxFor(all.get(j), placed.get(all.get(j).getKey()));
				assertFalse(all.get(i).getKey() + " and " + all.get(j).getKey() + " labels overlap",
					intersects(a, b, 0));
			}
		}
	}

	/**
	 * The worst case the config can produce: the largest font, with the bottom band reserved for
	 * the thirteen off-map codes. Both settings eat the same space, so if anything fails to place
	 * it fails here. Sizes come from {@link CodeLabelSize} rather than being retyped, so adding a
	 * larger font to that enum puts it under test automatically.
	 */
	@Test
	public void everyRingStillPlacesAtTheLargestSizeWithTheOffMapBandReserved()
	{
		MapDefinition map = definitions.getMap();
		for (CodeLabelSize size : CodeLabelSize.values())
		{
			int reserved = size.getHeight() + 1;
			Map<String, LabelPlacement> placed = LabelPlacement.solve(
				surface, surface,
				size.getWidth(), size.getHeight(), MARKER_RADIUS,
				0, 0, map.getSpriteWidth(), map.getSpriteHeight() - reserved);

			assertEquals("at size " + size + " these could not be placed: " + missing(placed),
				surface.size(), placed.size());
		}
	}

	@Test
	public void noLabelLeavesTheMap()
	{
		MapDefinition map = definitions.getMap();
		Map<String, LabelPlacement> placed = solveSurface(surface);
		for (LabelPlacement.Anchor anchor : surface)
		{
			int[] box = boxFor(anchor, placed.get(anchor.getKey()));
			assertTrue(anchor.getKey() + " label runs off the map: " + box[0] + "," + box[1],
				box[0] >= 0 && box[1] >= 0
					&& box[2] <= map.getSpriteWidth() && box[3] <= map.getSpriteHeight());
		}
	}

	/**
	 * Favourites-only mode labels a handful of rings while every marker still has to be avoided.
	 * Ten is the most favourites the game allows, so this is the worst case that mode can reach.
	 */
	@Test
	public void favouritesOnlyStillAvoidsEveryUnlabelledMarker()
	{
		List<LabelPlacement.Anchor> wanted = surface.subList(0, 10);
		Map<String, LabelPlacement> placed = solveSurface(wanted);
		assertEquals(wanted.size(), placed.size());

		for (LabelPlacement.Anchor anchor : wanted)
		{
			int[] box = boxFor(anchor, placed.get(anchor.getKey()));
			for (LabelPlacement.Anchor other : surface)
			{
				if (other == anchor)
				{
					continue;
				}
				assertFalse(anchor.getKey() + "'s label covers " + other.getKey() + "'s marker",
					intersects(box, boxFor(other, null), MARKER_RADIUS));
			}
		}
	}

	/**
	 * The solve must not depend on the order the caller happens to hand anchors over, or the same
	 * map would label differently between runs and every assertion above would be a coin toss.
	 * That is what the tie-break on the key buys.
	 */
	@Test
	public void theResultDoesNotDependOnInputOrder()
	{
		Map<String, LabelPlacement> forwards = solveSurface(surface);

		List<LabelPlacement.Anchor> shuffled = new ArrayList<>(surface);
		Collections.reverse(shuffled);
		Map<String, LabelPlacement> backwards = solveSurface(shuffled);

		assertEquals(forwards.keySet(), backwards.keySet());
		for (String code : forwards.keySet())
		{
			assertEquals(code + " moved when the input order changed",
				forwards.get(code).getOffsetX(), backwards.get(code).getOffsetX());
			assertEquals(code + " moved when the input order changed",
				forwards.get(code).getOffsetY(), backwards.get(code).getOffsetY());
		}
	}

	/** With nothing in the way a label takes the first candidate, which is below the marker. */
	@Test
	public void anIsolatedLabelGoesBelowItsMarker()
	{
		LabelPlacement.Anchor lone = new LabelPlacement.Anchor("AAA", 100, 100);
		Map<String, LabelPlacement> placed = LabelPlacement.solve(
			Collections.singletonList(lone), Collections.singletonList(lone),
			LABEL_WIDTH, LABEL_HEIGHT, MARKER_RADIUS, 0, 0, 200, 200);

		LabelPlacement spot = placed.get("AAA");
		assertNotNull(spot);
		assertEquals(0, spot.getOffsetX());
		assertTrue("expected the label below the marker", spot.getOffsetY() > 0);
	}

	/** A ring boxed in on every side is left unlabelled rather than drawn over something. */
	@Test
	public void aRingWithNowhereToGoIsLeftUnlabelled()
	{
		List<LabelPlacement.Anchor> all = new ArrayList<>();
		LabelPlacement.Anchor centre = new LabelPlacement.Anchor("MID", 100, 100);
		all.add(centre);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					all.add(new LabelPlacement.Anchor("N" + dx + dy, 100 + dx * 9, 100 + dy * 9));
				}
			}
		}

		Map<String, LabelPlacement> placed = LabelPlacement.solve(
			Collections.singletonList(centre), all,
			LABEL_WIDTH, LABEL_HEIGHT, MARKER_RADIUS, 0, 0, 200, 200);

		assertFalse("a boxed-in ring should get no label, not an overlapping one",
			placed.containsKey("MID"));
	}

	private int[] boxFor(LabelPlacement.Anchor anchor, LabelPlacement spot)
	{
		if (spot == null)
		{
			return new int[]{anchor.getX(), anchor.getY(), anchor.getX(), anchor.getY()};
		}
		int left = anchor.getX() + spot.getOffsetX() - LABEL_WIDTH / 2;
		int top = anchor.getY() + spot.getOffsetY() - LABEL_HEIGHT / 2;
		return new int[]{left, top, left + LABEL_WIDTH, top + LABEL_HEIGHT};
	}

	private String missing(Map<String, LabelPlacement> placed)
	{
		List<String> gaps = new ArrayList<>();
		for (LabelPlacement.Anchor anchor : surface)
		{
			if (!placed.containsKey(anchor.getKey()))
			{
				gaps.add(anchor.getKey());
			}
		}
		return gaps.toString();
	}

	/** {@code grow} inflates the second box, which turns a marker centre into its bounding square. */
	private static boolean intersects(int[] a, int[] b, int grow)
	{
		return a[0] < b[2] + grow && b[0] - grow < a[2]
			&& a[1] < b[3] + grow && b[1] - grow < a[3];
	}
}

package com.fairyringmap;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The sample row text is verbatim from the cache's fairyring table, "&lt;br&gt;" prefix and stray
 * trailing space included, because those are exactly the details a tidier fake would smooth away.
 */
public class LogRowTest
{
	private static final String MUDSKIPPER = "<br>Asgarnia: Mudskipper Point ";

	@Test
	public void codesComeOutOfTheColouredSpacedMenuTarget()
	{
		assertEquals("AIQ", LogRow.codeFromTarget("<col=ff981f>A I Q</col>"));
		assertEquals("DLS", LogRow.codeFromTarget("D L S"));
	}

	@Test
	public void anEmptyOrNonsenseTargetHasNoCode()
	{
		assertNull(LogRow.codeFromTarget(""));
		assertNull(LogRow.codeFromTarget(null));
		assertNull(LogRow.codeFromTarget("<col=ff981f>Travel log</col>"));
	}

	/**
	 * The dials carry A/D/C/B, I/L/K/J and P/S/R/Q, one letter from each in that order, so 64
	 * codes are possible. Anything using a letter from the wrong dial is not a code at all.
	 */
	@Test
	public void onlyLettersFromTheRightDialFormACode()
	{
		assertTrue(LogRow.isCode("AIQ"));
		assertTrue(LogRow.isCode("DLS"));
		assertFalse(LogRow.isCode("AAA"));
		assertFalse(LogRow.isCode("EIQ"));
		assertFalse(LogRow.isCode("AIT"));
		assertFalse(LogRow.isCode("AI"));
		assertFalse(LogRow.isCode("AIQR"));
		assertFalse(LogRow.isCode(null));
	}

	@Test
	public void aRowWithNoTextIsARingTheAccountCannotUse()
	{
		assertFalse(LogRow.isAvailable(""));
		assertFalse(LogRow.isAvailable(null));
		assertTrue(LogRow.isAvailable(MUDSKIPPER));
	}
}

package com.fairyringmap;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The projection is the one piece of maths in the plugin, so it is pinned hard: the world box and
 * sprite size below are the ones the shipped map was rendered with, and the landmark cases are
 * real fairy ring coordinates read out of the game's own database table.
 */
public class MapProjectionTest
{
	private static final int X0 = 1088;
	private static final int Y0 = 2304;
	private static final int X1 = 3904;
	private static final int Y1 = 4032;
	private static final int W = 508;
	private static final int H = 312;

	private final MapProjection projection = new MapProjection(X0, Y0, X1, Y1, W, H);

	@Test
	public void westEdgeIsColumnZero()
	{
		assertEquals(0, projection.pixelX(X0));
	}

	@Test
	public void eastEdgeIsTheFullWidth()
	{
		assertEquals(W, projection.pixelX(X1));
	}

	@Test
	public void northEdgeIsRowZeroBecauseImageYRunsTheOtherWay()
	{
		assertEquals(0, projection.pixelY(Y1));
	}

	@Test
	public void southEdgeIsTheFullHeight()
	{
		assertEquals(H, projection.pixelY(Y0));
	}

	@Test
	public void yDecreasesAsTheWorldGoesNorth()
	{
		assertTrue(projection.pixelY(3500) < projection.pixelY(3100));
	}

	@Test
	public void xIncreasesAsTheWorldGoesEast()
	{
		assertTrue(projection.pixelX(3100) > projection.pixelX(1500));
	}

	@Test
	public void centreOfTheBoxIsTheCentreOfTheSprite()
	{
		assertEquals(W / 2, projection.pixelX((X0 + X1) / 2));
		assertEquals(H / 2, projection.pixelY((Y0 + Y1) / 2));
	}

	/** DKR, Edgeville. Roughly two thirds east and just above the middle. */
	@Test
	public void edgevilleLandsWhereItShould()
	{
		int x = projection.pixelX(3129);
		int y = projection.pixelY(3496);
		assertEquals(368, x);
		assertEquals(97, y);
		assertTrue(projection.contains(3129, 3496));
	}

	/** CLR, Ape Atoll: far south, and well inside the sprite. */
	@Test
	public void apeAtollLandsInTheSouth()
	{
		assertTrue(projection.pixelY(2740) > H / 2);
		assertTrue(projection.contains(2743, 2740));
	}

	/** AIS, Auburn Valley in Varlamore: the western extreme of the surface rings. */
	@Test
	public void varlamoreIsInsideTheWesternEdge()
	{
		int x = projection.pixelX(1429);
		assertTrue(x > 0);
		assertTrue(x < W / 4);
		assertTrue(projection.contains(1429, 3324));
	}

	/** Zanaris sits in the same coordinate space thousands of tiles north of anything drawable. */
	@Test
	public void offSurfaceCoordinatesAreRejected()
	{
		assertFalse(projection.contains(2412, 4434));
		assertFalse(projection.contains(2926, 10455));
	}

	@Test
	public void tilesOutsideTheBoxAreRejected()
	{
		assertFalse(projection.contains(X0 - 20, 3000));
		assertFalse(projection.contains(X1 + 20, 3000));
		assertFalse(projection.contains(2500, Y0 - 20));
		assertFalse(projection.contains(2500, Y1 + 20));
	}

	/**
	 * Recorded rather than fixed: at roughly six and a half tiles to the pixel, a tile just outside
	 * the box rounds back onto the edge pixel and counts as inside. Harmless here — the box is the
	 * whole surface world and the nearest ring is two hundred tiles inside it — but worth knowing
	 * before reusing the class.
	 */
	@Test
	public void aTileJustOutsideRoundsOntoTheEdge()
	{
		assertTrue(projection.contains(X0 - 1, 3000));
		assertEquals(0, projection.pixelX(X0 - 1));
	}

	@Test(expected = IllegalArgumentException.class)
	public void anInvertedWorldBoxIsRejected()
	{
		new MapProjection(X1, Y0, X0, Y1, W, H);
	}

	@Test(expected = IllegalArgumentException.class)
	public void aZeroSizedSpriteIsRejected()
	{
		new MapProjection(X0, Y0, X1, Y1, 0, H);
	}
}

package com.fairyringmap;

import java.awt.image.BufferedImage;
import java.io.InputStream;
import javax.imageio.ImageIO;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Checks that the five marker sprites stay tellable apart, including for the ~8% of men with a
 * colour-vision deficiency.
 * <p>
 * This is shipped data, like the definitions JSON — the colours live only in the pixels of five
 * PNGs, produced by {@code cache-tools/tools/recolour-sprite.py}. Nothing in the source states
 * them, so a recolour that destroys a distinction produces no compile error, no test failure and
 * no visible symptom for anyone with normal colour vision. That is exactly what happened once:
 * {@code ring-fave} at {@code #FF4D6D} and {@code ring-locked} at {@code #6A6A6A} were 17 apart
 * under protanopia, and they mean opposite things — a favourite is reachable, a locked ring is
 * not.
 * <p>
 * The favourite is now {@code #E92100}, the red of the travel log's own favourited heart. What
 * rescued the pair was **saturation, not brightness**: a dark saturated red stays 174 from grey
 * under deuteranopia, where the pale rose greyed out and a brightened rose instead collapsed onto
 * the plain teal marker. Worst pair across the palette is now 171.
 * <p>
 * The measurement mirrors {@code cache-tools/tools/marker-audit.py}, which reports the full
 * matrix. This test only fails the build.
 */
public class MarkerColoursTest
{
	/**
	 * Below this two markers read as the same colour at eleven pixels. It is a rule of thumb
	 * rather than a standard — redmean has no perceptual threshold defined for it — so it is set
	 * where a distinction is plainly gone, not where it is merely reduced. The shipped sprites
	 * clear it by a factor of two on their worst pair.
	 */
	private static final double MIN_SEPARATION = 40;

	private static final String[] MARKERS = {
		"ring", "ring-hover", "ring-selected", "ring-locked", "ring-fave"
	};

	/**
	 * Brettel/Vienot-style simulation matrices, applied in sRGB. Approximate — an exact model
	 * would linearise first — but the question here is "have two colours collapsed onto each
	 * other", and that survives the approximation.
	 */
	private static final double[][][] DEFICIENCIES = {
		{{1, 0, 0}, {0, 1, 0}, {0, 0, 1}},
		{{0.367322, 0.860646, -0.227968}, {0.280085, 0.672501, 0.047413}, {-0.011820, 0.042940, 0.968881}},
		{{0.152286, 1.052583, -0.204868}, {0.114503, 0.786281, 0.099216}, {-0.003882, -0.048116, 1.051998}},
		{{1.255528, -0.076749, -0.178779}, {-0.078411, 0.930809, 0.147602}, {0.004733, 0.691367, 0.303900}},
	};

	private static final String[] DEFICIENCY_NAMES = {
		"normal vision", "deuteranopia", "protanopia", "tritanopia"
	};

	@Test
	public void noTwoMarkerStatesCollapseUnderAnyColourVisionDeficiency() throws Exception
	{
		int[][] colours = new int[MARKERS.length][];
		for (int i = 0; i < MARKERS.length; i++)
		{
			colours[i] = brightestOpaquePixel(MARKERS[i]);
		}

		for (int a = 0; a < MARKERS.length; a++)
		{
			for (int b = a + 1; b < MARKERS.length; b++)
			{
				for (int d = 0; d < DEFICIENCIES.length; d++)
				{
					double separation = redmean(
						simulate(colours[a], DEFICIENCIES[d]),
						simulate(colours[b], DEFICIENCIES[d]));

					assertTrue(String.format(
						"%s and %s are %.0f apart under %s, below the %.0f at which they read as "
							+ "the same colour. Re-run cache-tools/tools/marker-audit.py for the "
							+ "full matrix.",
						MARKERS[a], MARKERS[b], separation, DEFICIENCY_NAMES[d], MIN_SEPARATION),
						separation >= MIN_SEPARATION);
				}
			}
		}
	}

	/**
	 * What the eye reads off an eleven-pixel sprite is its brightest pixel: every other opaque
	 * pixel is that colour scaled down by the shared shading ramp, so the brightest one is the
	 * marker's colour and the mean is that colour darkened by however much of the sprite is
	 * shadow. Same rule as the audit tool, so the two agree.
	 */
	private int[] brightestOpaquePixel(String name) throws Exception
	{
		BufferedImage image;
		try (InputStream in = getClass().getResourceAsStream("/FairyRingMap/" + name + ".png"))
		{
			assertNotNull("/FairyRingMap/" + name + ".png is not on the classpath", in);
			image = ImageIO.read(in);
		}

		int[] brightest = null;
		int best = -1;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int argb = image.getRGB(x, y);
				if ((argb >>> 24) <= 128)
				{
					continue;
				}
				int r = (argb >> 16) & 0xFF;
				int g = (argb >> 8) & 0xFF;
				int bl = argb & 0xFF;
				if (r + g + bl > best)
				{
					best = r + g + bl;
					brightest = new int[]{r, g, bl};
				}
			}
		}

		assertNotNull(name + ".png has no opaque pixels", brightest);
		return brightest;
	}

	private static int[] simulate(int[] rgb, double[][] matrix)
	{
		int[] out = new int[3];
		for (int i = 0; i < 3; i++)
		{
			double v = matrix[i][0] * rgb[0] + matrix[i][1] * rgb[1] + matrix[i][2] * rgb[2];
			out[i] = Math.max(0, Math.min(255, (int) Math.round(v)));
		}
		return out;
	}

	/**
	 * Redmean: a cheap approximation of perceived colour difference that weights the red and blue
	 * terms by where in the red range the pair sits. Chosen over plain Euclidean RGB because the
	 * eye's sensitivity is not uniform across the cube, and over CIEDE2000 because this only has
	 * to answer "are these two obviously different", which it does without a colour library.
	 */
	private static double redmean(int[] a, int[] b)
	{
		double rm = (a[0] + b[0]) / 2.0;
		double dr = a[0] - b[0];
		double dg = a[1] - b[1];
		double db = a[2] - b[2];
		return Math.sqrt((2 + rm / 256) * dr * dr + 4 * dg * dg + (2 + (255 - rm) / 256) * db * db);
	}
}

package com.fairyringmap;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Each test walks the sequence the client actually produces - open, the game rebuilds the log,
 * close, reopen - because every bug this guards against only appeared across that sequence. A
 * single read followed by an assertion would have passed all three of them.
 */
public class RingStateTest
{
	/** Mudskipper Point, Zanaris and Miscellania: an ordinary ring, a favourite, a locked one. */
	private static final String AIQ = "AIQ";
	private static final String CKS = "CKS";
	private static final String CIP = "CIP";

	private static Map<String, Boolean> read(String... codeThenUnlocked)
	{
		Map<String, Boolean> read = new HashMap<>();
		for (int i = 0; i < codeThenUnlocked.length; i += 2)
		{
			read.put(codeThenUnlocked[i], Boolean.parseBoolean(codeThenUnlocked[i + 1]));
		}
		return read;
	}

	private static Map<String, Integer> slots(Object... codeThenSlot)
	{
		Map<String, Integer> slots = new HashMap<>();
		for (int i = 0; i < codeThenSlot.length; i += 2)
		{
			slots.put((String) codeThenSlot[i], (Integer) codeThenSlot[i + 1]);
		}
		return slots;
	}

	/** The state a session reaches after one ordinary opening of the travel log. */
	private static RingState afterFirstOpening()
	{
		RingState state = new RingState();
		state.recordFavourites(slots(CKS, 0));
		state.recordAvailability(read(AIQ, "true", CKS, "true", CIP, "false"));
		return state;
	}

	@Test
	public void beforeAnyReadEveryRingIsReachable()
	{
		RingState state = new RingState();
		assertTrue(state.reachable(AIQ, true));
		assertTrue(state.reachable(CIP, true));
	}

	/**
	 * Script 8080 can run before the server has filled the rows, when every ring reads locked.
	 * Taking that at face value is what opened the map grey.
	 */
	@Test
	public void aReadThatFindsNothingUnlockedDoesNotCountAsKnowing()
	{
		RingState state = new RingState();
		state.recordAvailability(read(AIQ, "false", CKS, "false", CIP, "false"));
		assertTrue(state.reachable(AIQ, true));
		assertTrue(state.reachable(CIP, true));
	}

	@Test
	public void oneUnlockedRingMakesTheRestOfTheReadBelievable()
	{
		RingState state = afterFirstOpening();
		assertTrue(state.reachable(AIQ, true));
		assertFalse(state.reachable(CIP, true));
	}

	/** The bug that cost a session: every reopen started from "nothing unlocked, nothing favourited". */
	@Test
	public void accountFactsSurviveTheInterfaceClosing()
	{
		RingState state = afterFirstOpening();
		state.interfaceClosed();

		// Reopened, and the game has not rebuilt the log yet.
		assertTrue(state.isUnlocked(AIQ));
		assertTrue(state.isFavourite(CKS));
		assertTrue(state.reachable(AIQ, true));
		assertFalse("a locked ring stays locked, not unknown", state.reachable(CIP, true));
	}

	/**
	 * Which row holds a favourite is only true of the list on screen. Carrying it across a close
	 * would point the filter at a row the server may have refilled with something else.
	 */
	@Test
	public void theFavouriteSlotDoesNotSurviveTheInterfaceClosing()
	{
		RingState state = afterFirstOpening();
		assertEquals(Integer.valueOf(0), state.favouriteSlot(CKS));

		state.interfaceClosed();

		assertNull(state.favouriteSlot(CKS));
		assertTrue(state.favouriteSlots().isEmpty());
	}

	@Test
	public void unfavouritingTakesTheColourAway()
	{
		RingState state = afterFirstOpening();
		state.recordFavourites(slots(AIQ, 0));
		assertFalse(state.isFavourite(CKS));
		assertTrue(state.isFavourite(AIQ));
		assertNull(state.favouriteSlot(CKS));
	}

	@Test
	public void aRingUnlockedMidSessionIsPickedUpByTheNextRead()
	{
		RingState state = afterFirstOpening();
		state.recordAvailability(read(CIP, "true"));
		assertTrue(state.reachable(CIP, true));
		assertTrue("a partial read leaves the rest alone", state.isUnlocked(AIQ));
	}

	/** While a search is in use the map is a picture of the search, whatever the account holds. */
	@Test
	public void aRingTheSearchExcludedIsUnreachableEvenWhenUnlocked()
	{
		RingState state = afterFirstOpening();
		assertFalse(state.reachable(AIQ, false));
		assertFalse(new RingState().reachable(AIQ, false));
	}
}

package com.fairyringmap;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import javax.imageio.ImageIO;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Pins the runtime recolour against the shipped sprites.
 * <p>
 * The shipped PNGs were generated by {@code cache-tools/tools/recolour-sprite.py}, and
 * {@link SpriteRecolour} is a port of that script so markers can be recoloured from config at
 * runtime. Two implementations of one formula drift, and the drift would be invisible: a slightly
 * wrong ramp still looks like a ring. So the test does not check properties of the output, it
 * checks that recolouring the base sprite reproduces the shipped one **exactly**.
 */
public class SpriteRecolourTest
{
	private BufferedImage load(String name) throws Exception
	{
		try (InputStream in = getClass().getResourceAsStream("/FairyRingMap/" + name))
		{
			assertNotNull(name + " is not on the classpath", in);
			return ImageIO.read(in);
		}
	}

	private void assertSame(BufferedImage expected, BufferedImage actual, String what)
	{
		assertEquals(what + ": width", expected.getWidth(), actual.getWidth());
		assertEquals(what + ": height", expected.getHeight(), actual.getHeight());
		for (int y = 0; y < expected.getHeight(); y++)
		{
			for (int x = 0; x < expected.getWidth(); x++)
			{
				int a = expected.getRGB(x, y);
				int b = actual.getRGB(x, y);
				// Fully transparent pixels may differ in their unused colour channels.
				if ((a >>> 24) == 0 && (b >>> 24) == 0)
				{
					continue;
				}
				assertEquals(String.format("%s: pixel %d,%d expected %08X got %08X", what, x, y, a, b),
					a, b);
			}
		}
	}

	/**
	 * The load-bearing one. {@code ring-fave.png} was produced by the Python script from
	 * {@code ring.png} and {@code #E92100}; doing the same here must give the same bytes.
	 */
	@Test
	public void matchesTheShippedFavouriteSprite() throws Exception
	{
		BufferedImage recoloured = SpriteRecolour.recolour(load("ring.png"), new Color(0xE92100));
		assertSame(load("ring-fave.png"), recoloured, "ring-fave");
	}

	/** Same again for the selected marker, which came from the same base and the same script. */
	@Test
	public void matchesTheShippedSelectedSprite() throws Exception
	{
		BufferedImage recoloured = SpriteRecolour.recolour(load("ring.png"), new Color(0xFF981F));
		assertSame(load("ring-selected.png"), recoloured, "ring-selected");
	}

	/**
	 * Recolouring is idempotent: the output is already on the ramp, so doing it again changes
	 * nothing. This is the property that matters at runtime, where a config change can recolour a
	 * sprite that has already been recoloured.
	 * <p>
	 * Note it is <em>not</em> true that recolouring {@code ring.png} to its own {@code #3FD9C8}
	 * returns {@code ring.png}. That sprite is the hand-drawn original and the other four were
	 * generated from it, so its soft edge pixels sit slightly off the ramp — pixel 0,0 is
	 * {@code 004040} at alpha 4 where the ramp gives {@code 13403B}. The difference is confined to
	 * nearly-transparent pixels and is invisible, but it is why {@link FairyRingMap} leaves the
	 * shipped sprite in place when the configured colour is the default.
	 */
	@Test
	public void recolouringIsIdempotent() throws Exception
	{
		Color target = new Color(0xE92100);
		BufferedImage once = SpriteRecolour.recolour(load("ring.png"), target);
		BufferedImage twice = SpriteRecolour.recolour(once, target);
		assertSame(once, twice, "recoloured twice");
	}

	/**
	 * An opaque target leaves alpha alone. Alpha is the marker's shape — a soft edge is what stops
	 * an eleven-pixel circle looking like a square — so a plain recolour must not touch it.
	 */
	@Test
	public void alphaIsPreserved() throws Exception
	{
		BufferedImage ring = load("ring.png");
		BufferedImage out = SpriteRecolour.recolour(ring, new Color(0x123456));
		for (int y = 0; y < ring.getHeight(); y++)
		{
			for (int x = 0; x < ring.getWidth(); x++)
			{
				assertEquals("alpha at " + x + "," + y,
					ring.getRGB(x, y) >>> 24, out.getRGB(x, y) >>> 24);
			}
		}
	}

	/**
	 * A translucent target changes nothing, because it cannot. The client's sprite format has no
	 * alpha channel, so marker transparency is widget opacity rather than pixels - pinning that
	 * here stops someone "fixing" this method to honour alpha and believing it worked.
	 */
	@Test
	public void aTranslucentTargetIsIgnoredBecauseSpritesHaveNoAlpha() throws Exception
	{
		BufferedImage ring = load("ring.png");
		BufferedImage opaque = SpriteRecolour.recolour(ring, new Color(0x12, 0x34, 0x56, 255));
		BufferedImage faded = SpriteRecolour.recolour(ring, new Color(0x12, 0x34, 0x56, 40));
		assertSame(opaque, faded, "alpha should not change the pixels");
	}

	/** The brightest pixel becomes the requested colour exactly; that is what "recolour" means. */
	@Test
	public void theBrightestPixelBecomesTheTargetColour() throws Exception
	{
		BufferedImage out = SpriteRecolour.recolour(load("ring.png"), new Color(0x8040C0));
		int brightest = 0;
		int best = -1;
		for (int y = 0; y < out.getHeight(); y++)
		{
			for (int x = 0; x < out.getWidth(); x++)
			{
				int argb = out.getRGB(x, y);
				if ((argb >>> 24) <= 128)
				{
					continue;
				}
				int sum = ((argb >> 16) & 0xFF) + ((argb >> 8) & 0xFF) + (argb & 0xFF);
				if (sum > best)
				{
					best = sum;
					brightest = argb & 0xFFFFFF;
				}
			}
		}
		assertTrue("expected some opaque pixels", best > 0);
		assertEquals(0x8040C0, brightest);
	}
}
